#include "plugin_favorites.hpp"
static void pluginFavoritesTests(){
    Json favorites=Json::array();Json effect={{"path","C:/Plugins/Room.vst3"},{"name","Room"},{"ok",true},{"instrument",false},{"vamp",false}};Json instrument={{"path","C:/Plugins/Synth.vst3"},{"name","Synth"},{"ok",true},{"instrument",true},{"vamp",false}};
    togglePluginStar(favorites,effect);togglePluginStar(favorites,instrument);auto native=nativePluginCatalog();togglePluginStar(favorites,native[0]);check(favorites.size()==3,"Any native FX, user FX and VST instrument can be starred");check(pluginIsStarred(favorites,"c:\\PLUGINS\\room.vst3"),"Star identity is case and slash insensitive on Windows");
    auto persisted=cleanFavorites(Json::parse(favorites.dump()));check(persisted==favorites,"Favorite metadata survives settings round trip");auto bad=Json::array({nullptr,"bad",Json{{"path",123}},effect,Json{{"path","c:\\plugins\\ROOM.vst3"}},Json{{"path","C:/a.wav"}}});check(cleanFavorites(bad).size()==1,"Invalid favorites and duplicate paths are sanitized");
    Json catalog=Json::array({effect,instrument,native[0]});auto master=pluginPickerEntries(2,native,catalog,favorites,true,false,L"");check(master.size()==2&&std::none_of(master.begin(),master.end(),[](auto&e){return e.value("instrument",false);}),"Master Starred only offers effects without deleting starred instruments");
    auto source=pluginPickerEntries(2,native,catalog,favorites,false,true,L"");check(source.size()==1&&source[0]["name"]=="Synth","Instrument picker offers the same shared favorites with an instrument filter");
    auto users=pluginPickerEntries(1,native,catalog,favorites,false,false,L"sYnTh");check(users.size()==1&&users[0]["instrument"]==true,"User tab searches case-insensitively and excludes native FX");check(pluginPickerEntries(0,native,catalog,favorites,true,false,L"").size()==47,"Vamp tab deduplicates catalog entries");
    togglePluginStar(favorites,Json{{"path","c:\\plugins\\ROOM.vst3"}});check(favorites.size()==2&&!pluginIsStarred(favorites,effect["path"]),"Unstar removes only the selected favorite");check(pluginPickerEntries(2,native,Json::array(),favorites,false,false,L"").size()==2,"Favorites stay available while a user plugin is offline or rescanning");
    std::ofstream(L"work/test-results/plugin-favorites.json")<<Json{{"passed",true},{"vamp_user_starred_tabs",true},{"effects_and_instruments",true},{"persisted_metadata",true},{"master_effect_filter",true},{"case_insensitive_identity",true},{"invalid_data_sanitized",true}}.dump(2);
}
